import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"29、【坎】 坎下坎上","description":"温公易说 - 29、【坎】 坎下坎上","frontmatter":{"title":"29、【坎】 坎下坎上","description":"温公易说 - 29、【坎】 坎下坎上"},"headers":[],"relativePath":"zh/classics/wengong/030.md","filePath":"zh/classics/wengong/030.md"}'),n={name:"zh/classics/wengong/030.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_29、【坎】-坎下坎上" tabindex="-1">29、【坎】 坎下坎上 <a class="header-anchor" href="#_29、【坎】-坎下坎上" aria-label="Permalink to “29、【坎】 坎下坎上”">​</a></h1><h3 id="彖曰-习坎-重险也。水流而不盈-行险而不失其信。维心亨-乃以刚中也。行有尚-往有功也。天险不可升也-地险山川丘陵也。王公设险以守其国-险之时用大矣哉。" tabindex="-1">彖曰：习坎，重险也。水流而不盈，行险而不失其信。维心亨，乃以刚中也。行有尚，往有功也。天险不可升也，地险山川丘陵也。王公设险以守其国，险之时用大矣哉。 <a class="header-anchor" href="#彖曰-习坎-重险也。水流而不盈-行险而不失其信。维心亨-乃以刚中也。行有尚-往有功也。天险不可升也-地险山川丘陵也。王公设险以守其国-险之时用大矣哉。" aria-label="Permalink to “彖曰：习坎，重险也。水流而不盈，行险而不失其信。维心亨，乃以刚中也。行有尚，往有功也。天险不可升也，地险山川丘陵也。王公设险以守其国，险之时用大矣哉。”">​</a></h3><h3 id="象曰-水洊至-习坎。君子以常德行-习教事。" tabindex="-1">象曰：水洊至，习坎。君子以常德行，习教事。 <a class="header-anchor" href="#象曰-水洊至-习坎。君子以常德行-习教事。" aria-label="Permalink to “象曰：水洊至，习坎。君子以常德行，习教事。”">​</a></h3><p>坎以常德行，习教事何也？水之为德，无有方圆曲直高下夷险，而不失其平者也。故君子以常德行，水之流也，习而不止，以成大川。人之学也，习而不止，以成大贤。故君子以习教事。</p><h3 id="初六-习坎-入于坎窞-凶-象曰-习坎入坎-失道凶也。" tabindex="-1">初六：习坎，入于坎窞，凶 象曰：习坎入坎，失道凶也。 <a class="header-anchor" href="#初六-习坎-入于坎窞-凶-象曰-习坎入坎-失道凶也。" aria-label="Permalink to “初六：习坎，入于坎窞，凶 象曰：习坎入坎，失道凶也。”">​</a></h3><p>初者事之始也，圣人之教人也，禁其始不禁其终，防其始不防其终。故坤之初六曰：履霜坚冰至。震之初九曰：震来虩虩，后笑言哑哑，吉。皆原其始而要终也。夫人之于险也，始皆有恐惧之心焉，及幸而济也，则狃以为常，至于失身而不自知也。是以圣人于险之初而戒其将来之祸，曰习坎入于坎窞，凶。窞者，坎中之坎也。</p><h3 id="九二-坎有险-求小得-象曰-求小得-未出中也。" tabindex="-1">九二：坎有险，求小得 象曰：求小得，未出中也。 <a class="header-anchor" href="#九二-坎有险-求小得-象曰-求小得-未出中也。" aria-label="Permalink to “九二：坎有险，求小得 象曰：求小得，未出中也。”">​</a></h3><h3 id="六三-来之坎坎-险且枕-入于坎窞-勿用-象曰-来之坎坎-终无功也。" tabindex="-1">六三：来之坎坎，险且枕，入于坎窞，勿用 象曰：来之坎坎，终无功也。 <a class="header-anchor" href="#六三-来之坎坎-险且枕-入于坎窞-勿用-象曰-来之坎坎-终无功也。" aria-label="Permalink to “六三：来之坎坎，险且枕，入于坎窞，勿用 象曰：来之坎坎，终无功也。”">​</a></h3><h3 id="六四-樽酒簋贰-用缶-纳约自牖-终无咎-象曰-樽酒簋贰-刚柔际也。" tabindex="-1">六四：樽酒簋贰，用缶，纳约自牖，终无咎 象曰：樽酒簋贰，刚柔际也。 <a class="header-anchor" href="#六四-樽酒簋贰-用缶-纳约自牖-终无咎-象曰-樽酒簋贰-刚柔际也。" aria-label="Permalink to “六四：樽酒簋贰，用缶，纳约自牖，终无咎 象曰：樽酒簋贰，刚柔际也。”">​</a></h3><h3 id="九五-坎不盈-祇既平-无咎-象曰-坎不盈-中未大也。" tabindex="-1">九五：坎不盈，祇既平，无咎 象曰：坎不盈，中未大也。 <a class="header-anchor" href="#九五-坎不盈-祇既平-无咎-象曰-坎不盈-中未大也。" aria-label="Permalink to “九五：坎不盈，祇既平，无咎 象曰：坎不盈，中未大也。”">​</a></h3><h3 id="上六-系用徽纆-置于丛棘-三岁不得-凶-象曰-上六失道-凶三岁也。" tabindex="-1">上六：系用徽纆，置于丛棘，三岁不得，凶 象曰：上六失道，凶三岁也。 <a class="header-anchor" href="#上六-系用徽纆-置于丛棘-三岁不得-凶-象曰-上六失道-凶三岁也。" aria-label="Permalink to “上六：系用徽纆，置于丛棘，三岁不得，凶 象曰：上六失道，凶三岁也。”">​</a></h3>',11)])])}const m=e(n,[["render",l]]);export{b as __pageData,m as default};
